const mockGetCartItem = jest.fn();

interface MedicationListTestGlobals {
  $api: {
    getCartItem: typeof mockGetCartItem;
    getDrugTags: typeof mockGetDrugTags;
    getDrugsByTags: typeof mockGetDrugsByTags;
    getMedsItem: typeof mockGetMedsItem;
  };
  $i18n: {
    t: (key: string) => string;
  };
  $NavigationActions: {
    navigate: jest.Mock;
  };
  $openWhatsApp: jest.Mock;
  $routeNames: {
    medicationDetailedScreen: string;
    shoppingCartScreen: string;
  };
}

const medicationGlobals = global as typeof globalThis & MedicationListTestGlobals;
medicationGlobals.$api = {
  getCartItem: mockGetCartItem,
  getDrugTags: mockGetDrugTags,
  getDrugsByTags: mockGetDrugsByTags,
